// Books are the library; contents belong to one book; ideas are unplaced thoughts.
(()=>{
 const $=s=>document.querySelector(s),library=$('[data-view="books"]'),ideas=$('[data-view="memories"]');
 $('[data-view="entries"]')?.remove();library.parentNode.prepend(library);$('[data-view="diary"]').textContent='Current book';ideas.firstChild.textContent='Ideas for later ';
 $('#books-view .section-head p').textContent='Your account library. Create a book, or pick up where you left off.';
 $('#memories-view h2').textContent='Ideas for later.';$('#memories-view .eyebrow').textContent='NOT IN A BOOK YET';$('#memories-view .section-head p').textContent='A holding place for unfinished thoughts. Choose a book when you are ready to place one on a page.';$('#new-memory').textContent='＋ Save a thought';$('#memory-dialog h2').textContent='An idea for later.';$('#memory-text').placeholder='A thought, a detail, or a story to write later…';
 const memoryButton=$('#open-memories');memoryButton.querySelector('span').textContent='Ideas for later';memoryButton.setAttribute('aria-label','Open Ideas for Later');memoryButton.title='Thoughts waiting for a book';$('#save-spread').hidden=true;
 const contents=document.createElement('dialog');contents.id='book-contents';contents.innerHTML='<button class="dialog-close" aria-label="Close contents">×</button><div class="eyebrow">INSIDE THIS BOOK</div><h2>Contents.</h2><p id="contents-book-name"></p><div id="contents-pages"></div>';document.body.append(contents);contents.querySelector('.dialog-close').onclick=()=>contents.close();
 const contentsButton=document.createElement('button');contentsButton.id='open-contents';contentsButton.textContent='Contents';contentsButton.setAttribute('aria-haspopup','dialog');$('.desk-top-actions').prepend(contentsButton);
 function showContents(){persistLibrary();const book=activeBook(),root=$('#contents-pages');$('#contents-book-name').textContent=book.title;root.replaceChildren();book.spreads.forEach((spread,index)=>{for(const side of ['left','right']){const page=index*2+(side==='left'?1:2),button=document.createElement('button'),number=document.createElement('small'),title=document.createElement('strong'),preview=document.createElement('span');button.className='contents-page';number.textContent='PAGE '+page;title.textContent=spread.heading||spread.diary?.[side]?.trim().split('\n')[0]?.slice(0,65)||'A page waiting for your story';preview.textContent=spread.diary?.[side]?.slice(0,120)||'Writing and memories belong here.';button.append(number,title,preview);button.onclick=()=>{contents.close();changeView('diary');goToSpread(index);openBook();window.diaryDictationTarget.selectPage(side)};root.append(button)}});contents.showModal()}
 contentsButton.onclick=showContents;window.showBookContents=showContents;
 const picker=document.createElement('dialog');picker.id='idea-book-picker';picker.innerHTML='<button class="dialog-close" aria-label="Close book picker">×</button><div class="eyebrow">GIVE THIS THOUGHT A PAGE</div><h2>Choose a book.</h2><p>Your idea stays in Ideas for Later. A copy will be added as a paper note on the book’s current spread.</p><div id="idea-book-list"></div>';document.body.append(picker);picker.querySelector('.dialog-close').onclick=()=>picker.close();
 window.placeDiaryIdea=text=>{if(!window.diaryAuth?.requireSignedIn())return;const root=$('#idea-book-list');root.replaceChildren();const own=books.filter(book=>!book.isSample);if(!own.length){const empty=document.createElement('p');empty.textContent='Create a book first, then come back to place this thought.';const create=document.createElement('button');create.className='primary';create.textContent='Make a book';create.onclick=()=>{picker.close();bookDialog()};root.append(empty,create)}for(const book of own){const button=document.createElement('button');button.className='idea-book-choice';button.textContent=book.title;button.onclick=()=>{if(!window.diaryAuth?.canEdit())return;picker.close();showBook(book.id);openBook();newPiece('paper',text);toast('A copy of your idea is now in '+book.title+'.')};root.append(button)}picker.showModal()};
 let requesting=false,exiting=false;
 window.enterBookFullscreen=async()=>{if(document.fullscreenElement||requesting||exiting)return;if(navigator.userActivation&& !navigator.userActivation.isActive)return;const request=document.documentElement.requestFullscreen;if(!request)return;requesting=true;try{await request.call(document.documentElement,{navigationUI:'hide'})}catch{/* Browser policy may require the explicit Full screen button. The tab-sized desk remains usable. */}finally{requesting=false;window.fitDiaryBook?.()}};
 window.leaveBookFullscreen=async()=>{if(!document.fullscreenElement||exiting)return;exiting=true;try{await document.exitFullscreen()}catch{}finally{exiting=false}};
 $('#close-book').addEventListener('click',()=>window.leaveBookFullscreen());
 document.addEventListener('diary-auth-change',()=>{contents.close();picker.close()});
})();
